source.jsLib:
var defaultUrl = 'https://manwa.me';

function _src() {
  var s = (this && this.source);
  if (!s) { try { s = source; } catch (e) { s = null; } }
  return s;
}

function Get(e) {
  var s = _src.call(this);
  if (!s) return null;
  var o = {};
  try { o = JSON.parse(s.getVariable()); } catch (err) { o = {}; }
  return o[e];
}

function URL() {
  var s = _src.call(this);
  if (!s) return defaultUrl;
  var o = {};
  try { o = JSON.parse(s.getVariable()); } catch (err) { o = {}; }
  if (o.custom) return o.custom;
  if (o.suffix && /^[a-z]{1,2}$/.test(o.suffix)) return 'https://manwa' + o.suffix + '.cc';
  return defaultUrl;
}

